const input = $json.body ?? $json;
const lead = input.lead ?? {};
if (!input.folio || !lead.name || !lead.whatsapp || !lead.service || lead.consent !== true) {
  throw new Error('Solicitud incompleta o sin consentimiento');
}
return [{ json: {
  ...input,
  workflow: 'SGM_WEB_LEAD_COMPLIANCE_V1',
  normalized_at: new Date().toISOString(),
  operational_state: 'captured'
}}];

const item = $json;
const c = item.compliance ?? {};
const destination = String(item.lead?.destination ?? '').trim();
const detected = destination || null;
const jurisdiction = {
  scope: 'multi_jurisdiction',
  detected_country: detected,
  country_detection_status: detected ? 'detected_from_destination' : 'pending',
  applicable_law: null,
  law_detection_status: 'pending'
};
return [{ json: {
  ...item,
  compliance: {
    ...c,
    status: 'pending_review',
    policy_code: 'SGM-COMPLIANCE-01',
    policy_version: '1.2',
    jurisdiction,
    human_approval_required: false,
    publication_allowed: false,
    decision: 'pending',
    crm_trace_required: true,
    next_action: detected ? 'automated_policy_review' : 'detect_jurisdiction'
  },
  operational_state: 'classified'
}}];
